// Shopping list items store quantity and unit separately, but some data
// (e.g. generated by AI) includes the unit inside the quantity string too,
// which would render as "230 g g". These helpers keep the display clean.

export function formatItemQuantity(
  quantity: string | null | undefined,
  unit: string | null | undefined
): string {
  const q = (quantity ?? '').trim();
  const u = (unit ?? '').trim();
  if (!u) return q;
  if (!q) return u;
  if (q.toLowerCase().endsWith(u.toLowerCase())) return q;
  return `${q} ${u}`;
}

// Used when pre-filling the edit dialog so saving an item back
// cleans the stored data instead of perpetuating the duplication.
export function stripTrailingUnit(
  quantity: string | null | undefined,
  unit: string | null | undefined
): string {
  const q = (quantity ?? '').trim();
  const u = (unit ?? '').trim();
  if (!u || !q) return q;
  if (q.toLowerCase().endsWith(u.toLowerCase())) {
    return q.slice(0, q.length - u.length).trim();
  }
  return q;
}
